  "implementation": "def solve(case):
    nodes = case.get('nodes')
    core_distance = case.get('core_distance')
    distances = case.get('distances')
    if not isinstance(nodes, list) or not isinstance(core_distance, dict) or not isinstance(distances, list):
        raise ValueError('Invalid input structure')
    if len(nodes) == 0:
        raise ValueError('No nodes')
    # Build list of mutual reachability edges
    edges = []
    for a, b, d in distances:
        ca = core_distance[a]
        cb = core_distance[b]
        w = max(ca, cb, d)
        # Canonicalize endpoints: smaller string first
        if a > b:
            a, b = b, a
        edges.append((w, a, b))
    # Sort by weight, then by first endpoint, then second endpoint
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find structure
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
